package com.paytrace.incident; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="incidents") public class IncidentEntity { @Id private UUID id; @Column(name="payment_id",nullable=false) private UUID paymentId; @Enumerated(EnumType.STRING) @Column(name="incident_type",nullable=false) private IncidentType incidentType; @Enumerated(EnumType.STRING) @Column(nullable=false) private Severity severity; @Column(name="detected_at",nullable=false) private Instant detectedAt; @Column(nullable=false) private String evidence; @Column(name="affected_components",nullable=false) private String affectedComponents; @Column(name="deterministic_facts",nullable=false) private String deterministicFacts; protected IncidentEntity(){} public IncidentEntity(Incident i){id=i.incidentId();paymentId=i.paymentId();incidentType=i.incidentType();severity=i.severity();detectedAt=i.detectedAt();evidence=String.join("|",i.evidence());affectedComponents=String.join("|",i.affectedComponents());deterministicFacts=String.join("|",i.deterministicFacts());} public Incident view(){return new Incident(id,paymentId,incidentType,severity,detectedAt,split(evidence),split(affectedComponents),split(deterministicFacts));} private static java.util.List<String> split(String v){return v.isEmpty()?java.util.List.of():java.util.List.of(v.split("\\|"));}}
